CREATE TABLE IF NOT EXISTS call_sessions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), restaurant_id uuid NOT NULL REFERENCES restaurants(id), provider_call_id text NOT NULL UNIQUE, caller_phone text, state text NOT NULL DEFAULT 'active', expires_at timestamptz NOT NULL, version integer NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS conversation_turns (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), session_id uuid NOT NULL REFERENCES call_sessions(id) ON DELETE CASCADE, sequence integer NOT NULL, role text NOT NULL, content text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(session_id, sequence));
CREATE TABLE IF NOT EXISTS draft_carts (session_id uuid PRIMARY KEY REFERENCES call_sessions(id) ON DELETE CASCADE, items_json text NOT NULL DEFAULT '[]', customer_name text, customer_phone text, confirmation_state text NOT NULL DEFAULT 'unconfirmed', version integer NOT NULL DEFAULT 0, updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS call_sessions_expiry_idx ON call_sessions (expires_at);
